import { defineElement, type UsaElement } from '../base';
import { defineMoName } from './mo-name';
import { make } from './moments';
import { hostSprings, tick, uid } from './micro-kit-16';
import { pilePose } from './damped-kit-18';
import css from './damped-kit-18.css?raw';

/**
 * A pile of cards (notifications, updates) that fans open into a list on damped springs: each card slides to its
 * place on its own, slightly later spring, so the list unrolls with a soft cascade and settles; closing gathers
 * them back behind the first. Collapsed, only the first card is reachable; the toggle is a real button with
 * `aria-expanded`, and clicking the pile opens it too.
 *
 * Content: each direct child is a card. Attributes: `open`, `more` (the toggle's text while closed; Show all),
 * `less` (Show less), `peek` (px each hidden card shows below the one above; 10), `gap` (px between open cards; 10),
 * `feel`, `haptics`.
 * Events: `usa:toggle` ({ open }).
 */
export interface UsaSpringStackElement extends UsaElement {
  open: boolean;
}

export function defineSpringStack(tag = 'usa-spring-stack'): CustomElementConstructor | undefined {
  const ctor = defineElement(tag, (Base) => class SpringStack extends Base {
    static get observedAttributes(): string[] {
      return ['open', 'more', 'less', 'peek', 'gap', 'feel', 'haptics'];
    }
    private _open = false;
    private _seen?: string | null;
    private _source: Node[] | null = null;
    private _set: ((on: boolean, user: boolean) => void) | null = null;
    get open(): boolean {
      return this._open;
    }
    set open(v: boolean) {
      if (this._set) this._set(!!v, false);
      else this._open = !!v;
    }
    mount(): void {
      if (!this._source) {
        const kids = [...this.children];
        this._source = kids.map((k) => k.cloneNode(true));
        kids.forEach((k) => k.remove());
      }
      const attr = this.getAttribute('open');
      if (attr !== this._seen) {
        this._seen = attr;
        this._open = this.flag('open');
      }
      const peek = Math.max(0, this.num('peek', 10));
      const gap = Math.max(0, this.num('gap', 10));
      const more = this.str('more', 'Show all');
      const less = this.str('less', 'Show less');
      const root = make('div', 'usa-dkit usa-dstack');
      const list = make('div', 'usa-dstack-list');
      list.id = uid('usa-dstack');
      list.setAttribute('role', 'list');
      const cards = this._source.map((node, i) => {
        const c = make('div', 'usa-dstack-card');
        c.setAttribute('role', 'listitem');
        c.style.zIndex = String(this._source!.length - i);
        c.append(node.cloneNode(true));
        list.append(c);
        return c;
      });
      const btn = make('button', 'usa-dstack-toggle');
      btn.type = 'button';
      btn.setAttribute('aria-controls', list.id);
      btn.hidden = cards.length < 2;
      root.append(list, btn);
      this.append(root);

      let heights = cards.map(() => 0);
      const measure = () => (heights = cards.map((c, i) => c.offsetHeight || heights[i] || 64));
      const init: Record<string, number> = { t: this._open ? 1 : 0 };
      cards.forEach((_, i) => (init[`c${i}`] = this._open ? 1 : 0));
      const group = hostSprings(this, init, (v) => {
        cards.forEach((c, i) => {
          const pose = pilePose(i, heights, v[`c${i}`], peek, gap);
          c.style.transform = `translateY(${pose.y}px) scale(${pose.scale})`;
          c.style.opacity = String(Math.max(0, Math.min(1, pose.opacity)));
        });
        const shut = (heights[0] || 0) + Math.min(cards.length - 1, 3) * peek;
        const full = heights.reduce((s, x) => s + x, 0) + gap * Math.max(0, cards.length - 1);
        list.style.height = `${Math.round((shut + (full - shut) * Math.max(0, v.t)) * 10) / 10}px`;
      });
      const paint = () => {
        btn.textContent = this._open ? less : `${more} (${cards.length})`;
        btn.setAttribute('aria-expanded', String(this._open));
        root.toggleAttribute('data-open', this._open);
        cards.forEach((c, i) => {
          const hide = !this._open && i > 0;
          c.toggleAttribute('inert', hide);
          c.setAttribute('aria-hidden', String(hide));
        });
      };
      const set = (on: boolean, user: boolean) => {
        if (on === this._open) return;
        measure();
        this._open = on;
        paint();
        group.set({ t: on ? 1 : 0 }, { spring: on ? { duration: 560, bounce: 0.14 } : { duration: 420, bounce: 0 } });
        cards.forEach((_, i) => {
          // a later card rides a slightly slower spring on the way out and a slightly quicker one on the way back
          const k = on ? i : cards.length - 1 - i;
          group.set({ [`c${i}`]: on ? 1 : 0 }, { spring: { duration: 460 + Math.min(k, 6) * 55, bounce: on ? 0.22 : 0.06 } });
        });
        if (user) tick(this, 6);
        this.emit('toggle', { open: on });
      };
      this._set = set;
      paint();
      measure();
      group.jump(init);
      this.listen(btn, 'click', () => set(!this._open, true));
      this.listen(list, 'click', (e: MouseEvent) => {
        if (this._open || (e.target as Element).closest?.('a, button, input, textarea, select')) return;
        set(true, true);
      });
      this.listen(root, 'keydown', (e: KeyboardEvent) => {
        if (e.key !== 'Escape' || !this._open) return;
        e.preventDefault();
        set(false, true);
        btn.focus({ preventScroll: true });
      });
      if (typeof ResizeObserver !== 'undefined') {
        const ro = new ResizeObserver(() => {
          measure();
          if (!group.animating) group.jump({ ...group.values });
        });
        cards.forEach((c) => ro.observe(c));
        this.onCleanup(() => ro.disconnect());
      }
      this.onCleanup(() => {
        group.stop();
        root.remove();
        this._set = null;
      });
    }
  }, { id: 'damped-kit-18', text: css });
  defineMoName(tag, ctor);
  return ctor;
}
